<template>
  <div class="page-container page-height-limit">
    <div class="row q-col-gutter-md">
      <!-- Main Content (Left Column) -->
      <div :class="showHelp ? 'col-12 col-md-8' : 'col-12'">
        <div class="settings-page-content">
          <!-- Page Header -->
          <div class="company-settings-page-header">
            <h2 class="company-settings-page-title">{{ $t('company') }}</h2>
            <p class="company-settings-page-subtitle">
              {{ $t('company_info_short') }}
            </p>
          </div>

          <!-- Company Information -->
          <docbits-accordion-panel
            v-model="expandedSections.company_info"
            icon="mdi:office-building"
            :title="$t('company')"
            :subtitle="$t('company_info_short')"
            @update:modelValue="onSectionToggle('company_info', $event)"
            data-test="sa-company-information"
          >
            <CompanyInformation />
          </docbits-accordion-panel>

          <!-- Company Preferences -->
          <docbits-accordion-panel
            v-model="expandedSections.preferences"
            icon="mdi:cog"
            :title="$t('preferences')"
            :subtitle="$t('preferences_short')"
            @update:modelValue="onSectionToggle('preferences', $event)"
          >
            <CompanyPreference />
          </docbits-accordion-panel>

          <!-- Company Theme -->
          <docbits-accordion-panel
            v-model="expandedSections.theme"
            icon="mdi:palette"
            :title="$t('company_theme')"
            :subtitle="$t('theme_short')"
            @update:modelValue="onSectionToggle('theme', $event)"
          >
            <CompanyTheme />
          </docbits-accordion-panel>

          <!-- E-mail domains (CORE-6075) — organisation admins of the current
               org only. The login matches a user without a membership to the
               organisation that owns their address's domain. -->
          <docbits-accordion-panel
            v-if="isOrgAdmin"
            v-model="expandedSections.orgDomains"
            icon="mdi:at"
            :title="$t('org_domains_title')"
            :subtitle="$t('org_domains_short')"
            @update:modelValue="onSectionToggle('orgDomains', $event)"
            data-test="org-domains-section"
          >
            <OrgDomains />
          </docbits-accordion-panel>

          <!-- Release Channel (MO-25 / DOCB-13404) — organisation admins of the
               current org only. v-if (not CSS hide) so the section - and its
               data-test hook - genuinely does not exist in the DOM for
               non-admins. -->
          <docbits-accordion-panel
            v-if="isOrgAdmin"
            v-model="expandedSections.releaseChannel"
            icon="mdi:source-branch"
            :title="$t('release_channel')"
            :subtitle="$t('release_channel_short')"
            @update:modelValue="onSectionToggle('releaseChannel', $event)"
            data-test="release-channel-section"
          >
            <ReleaseChannel />
          </docbits-accordion-panel>

          <!-- MFA enforcement (DOCB-13746) — organisation admins of the current
               org only. v-if (not CSS hide) so the section genuinely does not
               exist in the DOM for non-admins. -->
          <docbits-accordion-panel
            v-if="isOrgAdmin"
            v-model="expandedSections.mfaRequirement"
            icon="mdi:shield-lock"
            :title="$t('mfa_requirement')"
            :subtitle="$t('mfa_requirement_short')"
            @update:modelValue="onSectionToggle('mfaRequirement', $event)"
            data-test="mfa-requirement-section"
          >
            <MfaRequirement />
          </docbits-accordion-panel>

          <!-- Assistant switches (CORE-6147, CORE-6161) — organisation admins
               of the current org only. v-if (not CSS hide) so the section
               genuinely does not exist in the DOM for non-admins. -->
          <docbits-accordion-panel
            v-if="isOrgAdmin"
            v-model="expandedSections.settingsAssistantSwitch"
            icon="mdi:robot-outline"
            :title="$t('assistants_section_title')"
            :subtitle="$t('assistants_section_short')"
            @update:modelValue="onSectionToggle('settingsAssistantSwitch', $event)"
            data-test="settings-assistant-switch-section"
          >
            <div class="flex flex-col gap-6">
              <div data-test="settings-assistant-switch-block">
                <div class="font-semibold mb-2">{{ $t('settings_assistant_switch_title') }}</div>
                <SettingsAssistantSwitch />
              </div>
              <div data-test="validation-assistant-switch-block">
                <div class="font-semibold mb-2">{{ $t('validation_assistant_switch_title') }}</div>
                <SettingsAssistantSwitch
                  :setting-key="validation_assistant_enabled_setting"
                  text-prefix="validation_assistant_switch"
                />
              </div>
              <div data-test="validation-explainer-audio-switch-block">
                <div class="font-semibold mb-2">
                  {{ $t('validation_assistant_explainer_audio_switch_title') }}
                </div>
                <SettingsAssistantSwitch
                  :setting-key="validation_explainer_audio_enabled_setting"
                  text-prefix="validation_assistant_explainer_audio_switch"
                  default-on
                  :disabled="!validationAssistantEnabled"
                  disabled-hint="validation_assistant_explainer_audio_switch_needs_assistant"
                />
              </div>
            </div>
          </docbits-accordion-panel>
        </div>
      </div>

      <!-- Help Sidebar (Right Column) -->
      <div v-if="showHelp" class="col-12 col-md-4">
        <CompanySettingsHelp
          :activeSection="activeSection"
          @close="showHelp = false"
        />
      </div>

      <!-- Floating Help Button (when help hidden) -->
      <q-btn
        v-if="!showHelp"
        fab
        color="primary"
        icon="help_outline"
        class="floating-help-button"
        @click="showHelp = true"
      >
        <q-tooltip>Show Help</q-tooltip>
      </q-btn>
    </div>
  </div>
</template>

<script lang="ts">
import { computed, defineComponent, onMounted, ref } from 'vue';
import CompanyTheme from 'src/pages/Settings/Components/Company/Theme.vue';
import CompanyInformation from 'src/pages/Settings/Components/Company/CompanyInformation.vue';
import CompanyPreference from 'src/pages/Settings/Components/Company/CompanyPreference.vue';
import CompanySettingsHelp from 'src/pages/Settings/Components/Company/CompanySettingsHelp.vue';
import ReleaseChannel from 'src/pages/Settings/Components/Company/ReleaseChannel.vue';
import MfaRequirement from 'src/pages/Settings/Components/Company/MfaRequirement.vue';
import OrgDomains from 'src/pages/Settings/Components/Company/OrgDomains.vue';
import SettingsAssistantSwitch from 'src/pages/Settings/Components/Company/SettingsAssistantSwitch.vue';
import { getUserDetailFromkey } from 'src/utils/UserDetails';
import {
  validation_assistant_enabled_setting,
  validation_explainer_audio_enabled_setting,
} from 'src/constants';
import { useSettingStore } from 'src/store/main';
import { toBoolPreference } from 'src/utils/preferenceBool';

export default defineComponent({
  el: '#app',
  components: {
    CompanyTheme,
    CompanyInformation,
    CompanyPreference,
    CompanySettingsHelp,
    ReleaseChannel,
    MfaRequirement,
    OrgDomains,
    SettingsAssistantSwitch,
  },
  setup() {
    const activeSection = ref<
      | 'company_info'
      | 'preferences'
      | 'theme'
      | 'releaseChannel'
      | 'mfaRequirement'
      | 'orgDomains'
      | 'settingsAssistantSwitch'
      | null
    >(null);
    const showHelp = ref(true);
    const expandedSections = ref<Record<string, boolean>>({
      company_info: true,
      preferences: false,
      theme: false,
      releaseChannel: false,
      mfaRequirement: false,
      orgDomains: false,
      settingsAssistantSwitch: false,
    });
    // is_organisation_admin is org-scoped (NOT the global is_admin flag) —
    // same source of truth already used to gate admin-only settings
    // elsewhere (e.g. Settings/Pages/Dashboard.vue). Read in onMounted, not
    // synchronously here, because on a cold load the async user-details
    // fetch hasn't necessarily persisted it to LocalStorage yet.
    const isOrgAdmin = ref(false);

    function onSectionToggle(section: string, expanded: boolean) {
      if (expanded) {
        activeSection.value = section as typeof activeSection.value;
      }
    }

    onMounted(() => {
      isOrgAdmin.value = Boolean(
        JSON.parse(getUserDetailFromkey('is_organisation_admin') || 'false'),
      );
    });

    const settingStore = useSettingStore();
    const validationAssistantEnabled = computed(() =>
      toBoolPreference(
        settingStore.org_based_settings?.[validation_assistant_enabled_setting],
      ),
    );

    return {
      validation_assistant_enabled_setting,
      validation_explainer_audio_enabled_setting,
      validationAssistantEnabled,
      activeSection,
      showHelp,
      expandedSections,
      isOrgAdmin,
      onSectionToggle,
    };
  },
});
</script>

