import AbstractApiService from 'src/services/abstractApiService';
import { AUTH_URL } from 'src/pages/APIs';

export interface OrgDomain {
  id: string;
  org_id: string;
  domain: string;
  is_primary: boolean;
  created_by?: string | null;
  created_on?: string | null;
}

interface OrgDomainListResponse {
  success: boolean;
  domains: OrgDomain[];
}

interface OrgDomainResponse {
  success: boolean;
  domain: OrgDomain;
}

/**
 * CORE-6075 — e-mail domains an organisation owns.
 *
 * The login matches a user without a membership to the organisation that owns
 * the domain of their address, so a domain can belong to one organisation
 * only: the auth service answers 409 `DOMAIN_ALREADY_ASSIGNED` otherwise.
 * Same org-admin endpoint family as MfaRequirementApiService.
 */
export class OrgDomainApiService extends AbstractApiService {
  public constructor() {
    super({});
  }

  private url(orgId: string, domainId?: string): string {
    const base = `${AUTH_URL}/v2/organisations/${orgId}/domains`;
    return domainId ? `${base}/${domainId}` : base;
  }

  public async listDomains(orgId: string): Promise<OrgDomain[]> {
    const res = await this.getWithoutOrgId<OrgDomainListResponse>(
      this.url(orgId),
    );
    return res?.domains ?? [];
  }

  public async addDomain(
    orgId: string,
    domain: string,
    isPrimary = false,
  ): Promise<OrgDomain> {
    const res = await this.postWithoutOrgId<OrgDomainResponse>(
      this.url(orgId),
      {
        domain,
        is_primary: isPrimary,
      },
    );
    return res.domain;
  }

  public async makePrimary(
    orgId: string,
    domainId: string,
  ): Promise<OrgDomain> {
    const res = await this.patch<OrgDomainResponse>(
      this.url(orgId, domainId),
      {},
      { skipOrgId: true },
    );
    return res.domain;
  }

  public async removeDomain(orgId: string, domainId: string): Promise<void> {
    await this.deleteWithoutOrgId(this.url(orgId, domainId));
  }
}

export const orgDomainApiService = new OrgDomainApiService();
export default orgDomainApiService;
