<template>
  <div class="org-domains back-white" data-test="org-domains-card">
    <p class="org-domains-desc">{{ $t('org_domains_intro') }}</p>

    <div class="flex items-start gap-2">
      <q-input
        v-model="new_domain"
        dense
        outlined
        class="flex-1"
        :placeholder="$t('org_domains_add_placeholder')"
        :error="Boolean(field_error)"
        :error-message="field_error"
        :disable="saving"
        @update:model-value="field_error = ''"
        @keyup.enter="add_domain"
        data-test="org-domains-input"
      />
      <q-btn
        unelevated
        color="primary"
        :label="$t('org_domains_add')"
        :disable="saving || !new_domain.trim()"
        @click="add_domain"
        data-test="org-domains-add-btn"
      />
    </div>
    <p class="org-domains-hint">
      <Icon icon="mdi:information-outline" class="size-4 mr-1" />
      {{ $t('org_domains_unique_hint') }}
    </p>

    <div
      v-if="!loading && domains.length === 0"
      class="org-domains-empty"
      data-test="org-domains-empty"
    >
      {{ $t('org_domains_empty') }}
    </div>

    <ul v-else class="org-domains-list">
      <li
        v-for="d in domains"
        :key="d.id"
        class="org-domains-row"
        :data-test="`org-domains-row-${d.domain}`"
      >
        <span class="org-domains-name">{{ d.domain }}</span>
        <q-badge
          v-if="d.is_primary"
          color="primary"
          :label="$t('org_domains_primary')"
          data-test="org-domains-primary-badge"
        />
        <span class="flex-1" />
        <q-btn
          v-if="!d.is_primary"
          flat
          dense
          no-caps
          size="sm"
          :label="$t('org_domains_make_primary')"
          :disable="saving"
          @click="make_primary(d)"
          :data-test="`org-domains-make-primary-${d.domain}`"
        />
        <q-btn
          flat
          dense
          round
          size="sm"
          :disable="saving"
          @click="remove_domain(d)"
          :data-test="`org-domains-remove-${d.domain}`"
        >
          <Icon icon="mdi:delete-outline" class="size-4" />
          <q-tooltip>{{ $t('org_domains_remove') }}</q-tooltip>
        </q-btn>
      </li>
    </ul>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { Icon } from '@iconify/vue';
import { notify } from 'src/components/notifications/notify';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import orgDomainApiService, {
  type OrgDomain,
} from 'src/services/organization/OrgDomainApiService';

// message_code from the auth service -> Tolgee key shown on the field.
const ERROR_KEYS: Record<string, string> = {
  DOMAIN_ALREADY_ASSIGNED: 'org_domains_error_already_assigned',
  DOMAIN_INVALID: 'org_domains_error_invalid',
  DOMAIN_FREE_MAIL: 'org_domains_error_free_mail',
};

export default defineComponent({
  name: 'OrgDomains',
  components: { Icon },
  data() {
    return {
      domains: [] as OrgDomain[],
      new_domain: '',
      field_error: '',
      loading: false,
      saving: false,
    };
  },
  mounted() {
    this.load_domains();
  },
  methods: {
    error_text(err: unknown): string {
      const code = (err as { message_code?: string } | null)?.message_code;
      return this.$t(ERROR_KEYS[code ?? ''] ?? 'org_domains_error_generic');
    },
    async load_domains() {
      const orgId = getOrgId();
      if (!orgId) return;
      this.loading = true;
      try {
        this.domains = await orgDomainApiService.listDomains(orgId);
      } catch (err) {
        notify.error(this.error_text(err));
      } finally {
        this.loading = false;
      }
    },
    async add_domain() {
      const value = this.new_domain.trim();
      const orgId = getOrgId();
      if (!value || !orgId || this.saving) return;
      this.saving = true;
      this.field_error = '';
      try {
        await orgDomainApiService.addDomain(
          orgId,
          value,
          this.domains.length === 0,
        );
        this.new_domain = '';
        await this.load_domains();
        notify.success(this.$t('MSG_SAVE'));
      } catch (err) {
        // A taken, public or malformed domain is shown on the field itself.
        this.field_error = this.error_text(err);
      } finally {
        this.saving = false;
      }
    },
    async make_primary(domain: OrgDomain) {
      const orgId = getOrgId();
      if (!orgId) return;
      this.saving = true;
      try {
        await orgDomainApiService.makePrimary(orgId, domain.id);
        await this.load_domains();
      } catch (err) {
        notify.error(this.error_text(err));
      } finally {
        this.saving = false;
      }
    },
    async remove_domain(domain: OrgDomain) {
      const orgId = getOrgId();
      if (!orgId) return;
      this.saving = true;
      try {
        await orgDomainApiService.removeDomain(orgId, domain.id);
        await this.load_domains();
      } catch (err) {
        notify.error(this.error_text(err));
      } finally {
        this.saving = false;
      }
    },
  },
});
</script>

