<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { orgApiService } from 'src/services';
import type { dynamicObj } from 'src/pages/assets';
import Loader from 'src/components/Loader.vue';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import { isUndefinedOrNull } from 'src/utils/general';
import { useLangOriginDropdownStore, useSettingStore } from 'src/store/main';

export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  components: {
    Loader,
  },
  data() {
    return {
      origins: ref([]),
      userDialog: ref(false),
      api_key: '',
    };
  },
  setup() {
    const setting_store = useSettingStore();
    const { updateSetting } = setting_store;
    const { user_settings } = storeToRefs(setting_store);

    const language_origin_dropdown = useLangOriginDropdownStore();
    const { getLanguageIfEmpty } = language_origin_dropdown;
    const { language_origins, language_origins_loading } = storeToRefs(
      language_origin_dropdown,
    );

    let company_info = {} as { [k: string]: any };
    return {
      language_origins_loading,
      language_origins,
      getLanguageIfEmpty,
      updateSetting,
      user_settings,
      company_info: ref(company_info),
    };
  },
  mounted() {
    this.setupOriginList();
    this.fetchOrgSettings();
    logInfo(this.user_settings);
  },
  computed: {
    isUSFormat(): boolean {
      const usCountries = [
        'United States',
        'USA',
        'US',
        'United States of America',
      ];
      return usCountries.includes(this.company_info?.country || '');
    },
  },
  methods: {
    async fetchOrgSettings() {
      try {
        this.showLoading();
        const response = await orgApiService.get();
        for (let key in response) {
          let value = response[key];
          if (response[key] == 'null' || response[key] === 'undefined') {
            value = '';
          }
          this.company_info[key] = value;
        }

        this.setupDefaultOrigin();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    setupDefaultOrigin() {
      if (this.company_info['country'] == 'Deutschland') {
        this.company_info['country'] = '';
      }
    },

    async save_org() {
      try {
        this.showLoading();
        let data = {
          name: this.company_info.name,
          street: this.company_info.street,
          plz: this.company_info.plz,
          city: this.company_info.city,
          state: this.company_info.state,
          country: this.company_info.country,
          company_id: this.company_info.company_id,
          tax_id: this.company_info.tax_id,
          commercial_id: this.company_info.commercial_id,
          email: this.company_info.email,
          phone_number: this.company_info.phone_number,
        } as dynamicObj;

        data = this.handleDataValidation(data);

        await orgApiService.set(data);
        notify.success(this.$t('company_save_success'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(this.$t('company_save_error'));
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    handleDataValidation(data: any) {
      for (let key in data) {
        if (isUndefinedOrNull(data[key])) {
          data[key] = '';
        }
      }

      return data as dynamicObj;
    },

    async setupOriginList() {
      try {
        await this.getLanguageIfEmpty();
        this.origins = JSON.parse(JSON.stringify(this.language_origins));
        this.origins.shift();
      } catch (err) {
        logError(err);
      }
    },
  },
});
</script>

