import AbstractApiService from 'src/services/abstractApiService';
import { AUTH_URL } from 'src/pages/APIs';

export interface OrganisationMfaRequirementResponse {
  org_id: string;
  require_mfa: boolean;
  [key: string]: unknown;
}

export interface OrganisationMfaAdoptionResponse {
  org_id: string;
  total_members: number;
  mfa_enabled: number;
  adoption_pct: number;
  by_method: { totp: number; email: number; webauthn: number };
  require_mfa: boolean;
  [key: string]: unknown;
}

/**
 * DOCB-13746 — per-organisation MFA enforcement.
 *
 * When require_mfa is on, password logins by members of this org are gated on a
 * second factor (SSO logins are exempt by design). Read + write go through the
 * dedicated org-admin endpoint, NOT GET /v2/organisations/{orgId} (which is
 * gated on the GLOBAL user.is_admin flag — an org-admin gets a 500 there). This
 * mirrors ReleaseChannelApiService 1:1.
 */
export class MfaRequirementApiService extends AbstractApiService {
  public constructor() {
    super({});
  }

  public async getMfaRequirement(
    orgId: string,
  ): Promise<OrganisationMfaRequirementResponse> {
    return this.getWithoutOrgId<OrganisationMfaRequirementResponse>(
      `${AUTH_URL}/v2/organisations/${orgId}/mfa-requirement`,
    );
  }

  public async updateMfaRequirement(
    orgId: string,
    requireMfa: boolean,
  ): Promise<OrganisationMfaRequirementResponse> {
    // AbstractApiService.put() also appends org_id to the JSON body; the backend
    // schema (Meta.unknown = EXCLUDE) drops it, and the org_id that matters is
    // the one in the URL path.
    return this.put<OrganisationMfaRequirementResponse>(
      `${AUTH_URL}/v2/organisations/${orgId}/mfa-requirement`,
      { require_mfa: requireMfa },
    );
  }

  // DOCB-13746 admin visibility: read-only MFA adoption stats for this org
  // (org-admin gated, same auth as the requirement endpoint).
  public async getMfaAdoption(
    orgId: string,
  ): Promise<OrganisationMfaAdoptionResponse> {
    return this.getWithoutOrgId<OrganisationMfaAdoptionResponse>(
      `${AUTH_URL}/v2/organisations/${orgId}/mfa-adoption`,
    );
  }
}

export const mfaRequirementApiService = new MfaRequirementApiService();
export default mfaRequirementApiService;
