<template>
  <div class="mfa-req-form back-white" data-test="mfa-requirement-card">
    <p class="mfa-req-desc">{{ $t('mfa_requirement_intro') }}</p>

    <q-toggle
      dense
      v-model="require_mfa"
      :label="$t('mfa_requirement_toggle_label')"
      color="primary"
      :disable="enableBlocked"
      data-test="mfa-requirement-toggle"
    />

    <!-- DOCB-13742 stopgap: enabling is blocked until the login-time MFA
         enrollment flow ships — enforcing now locks out every member (incl.
         the admin) who has no enrolled second factor. Disabling stays
         possible so an already-enforcing org can be unlocked. -->
    <p
      v-if="enableBlocked"
      class="mfa-req-hint"
      data-test="mfa-requirement-enable-blocked-hint"
    >
      <q-icon name="mdi-information-outline" size="16px" class="q-mr-xs" />
      {{ $t('mfa_requirement_enable_blocked_hint') }}
    </p>

    <p class="mfa-req-hint" data-test="mfa-requirement-effect-hint">
      <q-icon name="mdi-information-outline" size="16px" class="q-mr-xs" />
      {{ $t('mfa_requirement_effect_hint') }}
    </p>

    <!-- DOCB-13746: admin visibility — MFA adoption across the org -->
    <div v-if="adoption" class="mfa-adoption" data-test="mfa-adoption">
      <div class="mfa-adoption-head">
        <span class="text-weight-medium">{{ $t('mfa_adoption_title') }}</span>
        <span class="mfa-adoption-pct" data-test="mfa-adoption-pct">
          {{ adoption.adoption_pct }}%
        </span>
      </div>
      <q-linear-progress
        :value="adoption.adoption_pct / 100"
        color="primary"
        track-color="grey-3"
        rounded
        size="8px"
        class="q-my-xs"
      />
      <div class="mfa-adoption-sub">
        {{ $t('mfa_adoption_enrolled', { enabled: adoption.mfa_enabled, total: adoption.total_members }) }}
      </div>
      <div class="mfa-adoption-methods">
        <span>{{ $t('mfa_settings_method_totp') }}: {{ adoption.by_method.totp }}</span>
        <span>{{ $t('mfa_settings_method_email') }}: {{ adoption.by_method.email }}</span>
        <span>{{ $t('mfa_settings_method_passkey') }}: {{ adoption.by_method.webauthn }}</span>
      </div>
    </div>

    <div class="mfa-req-footer">
      <q-btn
        unelevated
        :label="$t('save')"
        color="primary"
        :disable="!hasChanged"
        @click="save_mfa_requirement"
        size="md"
        data-test="mfa-requirement-save-btn"
      />
    </div>
  </div>
  <Loader />
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent } from 'vue';
import Loader from 'src/components/Loader.vue';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import mfaRequirementApiService, {
  type OrganisationMfaAdoptionResponse,
} from 'src/services/organization/MfaRequirementApiService';

// DOCB-13746: org-admin toggle for Organisation.require_mfa. When on, members
// must clear a second factor to log in with a password (SSO logins are exempt —
// their IdP already enforces MFA). Mirrors ReleaseChannel.vue's load/save shape.
export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  components: {
    Loader,
  },
  data() {
    return {
      require_mfa: false,
      saved_require_mfa: false,
      adoption: null as OrganisationMfaAdoptionResponse | null,
    };
  },
  computed: {
    hasChanged(): boolean {
      return this.require_mfa !== this.saved_require_mfa;
    },
    // DOCB-13742 stopgap: while the saved setting is OFF, enabling is blocked
    // (login-time enrollment does not exist yet — enforcing would lock out
    // every member without an enrolled second factor, including the admin).
    // While the saved setting is ON the toggle stays usable so the org can
    // still be unlocked by turning enforcement OFF.
    enableBlocked(): boolean {
      return !this.saved_require_mfa;
    },
  },
  mounted() {
    this.load_mfa_requirement();
  },
  methods: {
    async load_mfa_requirement() {
      try {
        this.showLoading();
        const orgId = getOrgId();
        if (!orgId) {
          return;
        }
        const response = await mfaRequirementApiService.getMfaRequirement(orgId);
        this.require_mfa = Boolean(response?.require_mfa);
        this.saved_require_mfa = this.require_mfa;
        // Adoption stats are best-effort — a failure here must not break the
        // toggle, so load them separately and swallow their error.
        try {
          this.adoption = await mfaRequirementApiService.getMfaAdoption(orgId);
        } catch {
          this.adoption = null;
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    async save_mfa_requirement() {
      // DOCB-13742 stopgap guard: never persist require_mfa=true while
      // enabling is blocked (belt-and-braces on top of the disabled toggle).
      if (this.enableBlocked && this.require_mfa) {
        return;
      }
      try {
        this.showLoading();
        const orgId = getOrgId();
        if (!orgId) {
          throw new Error('Organisation ID not found');
        }
        await mfaRequirementApiService.updateMfaRequirement(orgId, this.require_mfa);
        this.saved_require_mfa = this.require_mfa;
        notify.success(this.$t('MSG_SAVE'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
  },
});
</script>

