<template>
  <div class="sas-form back-white" data-test="settings-assistant-switch-card">
    <p class="sas-desc">{{ $t(`${textPrefix}_intro`) }}</p>

    <q-toggle
      dense
      v-model="enabled"
      :label="$t(`${textPrefix}_label`)"
      :aria-label="$t(`${textPrefix}_label`)"
      :disable="saving || disabled"
      color="primary"
      @update:model-value="onToggle"
      data-test="settings-assistant-switch-toggle"
    />

    <p class="sas-hint" data-test="settings-assistant-switch-hint">
      <q-icon name="mdi-information-outline" size="16px" class="q-mr-xs" />
      {{ $t(`${textPrefix}_hint`) }}
    </p>
    <p
      v-if="disabled && disabledHint"
      class="sas-hint"
      data-test="settings-assistant-switch-disabled-hint"
    >
      {{ $t(disabledHint) }}
    </p>
  </div>
</template>

<script lang="ts">
// Shared across instances of the same setting: the latest save wins, so a slow
// response of an earlier (unmounted) instance can never overwrite a newer write.
const saveSeqs: Record<string, number> = {};
</script>

<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue';
import { storeToRefs } from 'pinia';
import { i18n } from 'src/boot/i18n';
import { notify } from 'src/components/notifications/notify';
import { settings_assistant_enabled_setting } from 'src/constants';
import { preferencesService } from 'src/services/preferences/preferencesService';
import { useSettingStore } from 'src/store/main';
import { toBoolPreference } from 'src/utils/preferenceBool';

// CORE-6147: org-admin switch for SETTINGS_ASSISTANT_ENABLED — the flag
// SettingsLayout reads (org_based_settings) to offer the assistant chat.
// Default stays OFF; the store is updated after a successful save so the
// layout flips without a reload.
// CORE-6161: the same switch serves VALIDATION_ASSISTANT_ENABLED.
const props = withDefaults(
  defineProps<{
    settingKey?: string;
    textPrefix?: string;
    // CORE-6235: an unset preference reads as ON (the voice-over switch).
    defaultOn?: boolean;
    disabled?: boolean;
    disabledHint?: string;
  }>(),
  {
    settingKey: settings_assistant_enabled_setting,
    textPrefix: 'settings_assistant_switch',
    defaultOn: false,
    disabled: false,
    disabledHint: '',
  },
);

const settingsStore = useSettingStore();
const { org_based_settings } = storeToRefs(settingsStore);

const persisted = computed(() => {
  const raw = org_based_settings.value[props.settingKey];
  if (props.defaultOn && (raw === undefined || raw === null || raw === '')) {
    return true;
  }
  return toBoolPreference(raw);
});
const enabled = ref(persisted.value);
const saving = ref(false);

// The org settings can hydrate after mount — follow the store unless a save is
// in flight (the optimistic value must not be overwritten mid-save). Once the
// save settles the switch is reconciled with the CURRENT store value, so a
// hydration that arrived during the request is never lost.
watch([persisted, saving], ([value, isSaving]) => {
  if (!isSaving) enabled.value = value;
});

// setOrgPreference reports success for every resolved HTTP response, while the
// API answers 200 with { success: false, message } when the write failed — so
// the response body has to be checked as well.
const isFailedSave = (result: unknown): boolean => {
  const res = result as { success?: boolean; data?: { success?: boolean } };
  return !res || res.success === false || res.data?.success === false;
};

// Instance-local state and toasts are off-limits after unmount; the store write
// of the latest save is not — a save that finishes after the admin left the page
// must still flip the layout.
let disposed = false;
onBeforeUnmount(() => {
  disposed = true;
});

const onToggle = async (newValue: boolean) => {
  if (saving.value) return;
  saving.value = true;
  const key = props.settingKey;
  const mySeq = (saveSeqs[key] = (saveSeqs[key] ?? 0) + 1);
  try {
    const result = await preferencesService.setOrgPreference(
      props.settingKey,
      newValue ? 'true' : 'false',
    );
    if (isFailedSave(result)) {
      throw new Error(
        (result as { error?: string })?.error || 'Failed to set org preference',
      );
    }
    if (mySeq !== saveSeqs[key]) return;
    org_based_settings.value[props.settingKey] = newValue
      ? 'true'
      : 'false';
    if (!disposed) {
      notify.success(
        i18n.t(
          newValue
            ? `${props.textPrefix}_enabled_toast`
            : `${props.textPrefix}_disabled_toast`,
        ),
      );
    }
  } catch (error) {
    console.error('Failed to save settings assistant preference:', error);
    if (!disposed && mySeq === saveSeqs[key]) {
      notify.error(i18n.t(`${props.textPrefix}_error_toast`));
    }
  } finally {
    if (!disposed) {
      saving.value = false;
      if (mySeq === saveSeqs[key]) enabled.value = persisted.value;
    }
  }
};

defineExpose({ enabled, saving, onToggle });
</script>

<style scoped lang="scss">
.sas-desc {
  font-size: 0.8125rem;
  color: var(--dashboard-text-disabled, #9ca3af);
  margin: 0 0 0.75rem 0;
}

.sas-hint {
  display: flex;
  align-items: center;
  font-size: 0.75rem;
  color: var(--dashboard-text-disabled, #9ca3af);
  margin: 1rem 0 0 0;
}
</style>
